 function collectionReceiptText(t:any,readings:any[]){return [data.company,data.companyFiscal.address,data.companyFiscal.vat?`P.IVA ${data.companyFiscal.vat}`:'',data.companyFiscal.fiscalCode?`C.F. ${data.companyFiscal.fiscalCode}`:'','--------------------------------',selectedLocal?.ragioneSociale||selectedLocal?.name||'',selectedLocal?.partitaIva?`P.IVA ${selectedLocal.partitaIva}`:'',selectedLocal?.codiceFiscale?`C.F. ${selectedLocal.codiceFiscale}`:'','--------------------------------',`INSEGNA: ${selectedLocal?.insegna||selectedLocal?.name||''}`,'--------------------------------',`DATA: ${new Date().toLocaleString('it-IT')}`,`ESATTORE: ${auth.name}`,'--------------------------------',...readings.flatMap((r:any)=>[`${r.model||'AWP'} · ${r.machineId}`,`P IN: ${r.partialIn}   P OUT: ${r.partialOut}`,`T IN: ${r.globalIn}   T OUT: ${r.globalOut}`,`CASS: ${money(r.drawer)}   TASS: ${money(r.taxes)}`,`GEST: ${money(r.managerShare)}   ESRC: ${money(r.exerciseShare)}`,...(Number(r.serviceShare)>0?[`SERV: ${money(r.serviceShare)}`]:[]),'']), '--------------------------------',`Giocato: ${money(t.played)}`,`Pagato: ${money(t.paid)}`,`Cassa: ${money(t.drawer)}`,`Tasse: ${money(t.taxes)}`,`Riscosso: ${money(t.collected)}`,`Acconti: ${money(t.deposits)}`,`Quota gestore: ${money(t.managerShare)}`,`Quota esercente: ${money(t.exerciseShare)}`,...(Number(t.serviceShare)>0?[`Quota service: ${money(t.serviceShare)}`]:[]),`Pagamento: ${t.paymentMethod==='cash'?'Contanti':'Bonifico'}`].filter(Boolean).join('\n')}
