 useEffect(()=>{if(!scan)return;let stream:MediaStream|undefined;let active=true;async function start(){try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});if(videoRef.current)videoRef.current.srcObject=stream;const detector='BarcodeDetector'in window?new (window as any).BarcodeDetector({formats:['qr_code']}):null;if(detector){const check=async()=>{if(!active||!videoRef.current)return;try{const codes=await detector.detect(videoRef.current);if(codes[0]){setQuery(codes[0].rawValue);setPage('Apparecchi');setScan(false);setToast('Codice letto');return}}catch{}requestAnimationFrame(check)};requestAnimationFrame(check)}}catch{setToast('Consenti l’accesso alla fotocamera')}}start();return()=>{active=false;stream?.getTracks().forEach(t=>t.stop())}},[scan]);
 const machines=data.machines; const locals=useMemo(()=>[...new Set(machines.map(m=>m.local).filter(Boolean))].sort(),[machines]); const visible=machines.filter(m=>Object.values(m).some(v=>String(v??'').toLowerCase().includes(query.toLowerCase())));
