 const searchResults=useMemo(()=>{const q=globalSearch.trim().toLowerCase();if(!q)return[];const matches:Array<{kind:'machine'|'local'|'pda';id:string;title:string;subtitle:string}>=[];for(const l of data.locals){const hay=[l.name,l.localCode,l.pdvCode,l.address,l.comune,l.ragioneSociale,l.insegna,l.contactName,l.phone,l.partitaIva].join(' ').toLowerCase();if(hay.includes(q))matches.push({kind:'local',id:l.localKey,title:l.name,subtitle:`Locale · ${[l.comune,l.address].filter(Boolean).join(' · ')}`})}for(const m of machines){const hay=Object.values(m).map(v=>String(v??'')).join(' ').toLowerCase();if(hay.includes(q))matches.push({kind:'machine',id:m.id,title:m.id,subtitle:`Macchina · ${m.local}${m.model?` · ${m.model}`:''}`})}for(const mac of pdas){if(mac.toLowerCase().includes(q))matches.push({kind:'pda',id:mac,title:mac,subtitle:`PDA · ${machines.filter(m=>m.pdaMac===mac).length} macchine collegate`})}return matches.slice(0,12)},[globalSearch,data.locals,machines,pdas]);
