 const today=new Date().toDateString(), todayDeposits=data.deposits.filter(d=>new Date(d.date).toDateString()===today), totalToday=todayDeposits.reduce((s,d)=>s+d.amount,0);
 async function importFile(file?:File){if(!file)return;try{const XLSX=await import('xlsx');const buffer=await file.arrayBuffer(),book=XLSX.read(buffer,{type:'array',cellText:true,cellDates:false});const sheet=book.Sheets[book.SheetNames[0]],rows=XLSX.utils.sheet_to_json<Record<string,unknown>>(sheet,{defval:'',raw:false});if(!rows.length)throw new Error('Nessuna riga trovata');const map:Record<string,string>={'CODEID':'id','DENOMIN. SEDE':'local','CODICE SEDE':'localCode','CODICE PDV AAMS':'pdvCode','MACADDRESS PDA':'pdaMac','COMUNE':'comune','PROVINCIA':'provincia','INDIRIZZO':'address','MODELLO':'model','CODICE MODELLO':'codeModel','CODEID PROVV':'codeProvv','DESCR. STATO':'status','CNTTOTIN':'cntIn','CNTTOTOT':'cntOut','CODICE IS ESERCENTE':'exerciseCode'};const converted=rows.map(row=>{const m:any={};for(const [src,dst]of Object.entries(map))m[dst]=String(row[src]??'').trim();for(const [k,v]of Object.entries(row))m[k]=String(v??'').trim();return m as Machine}).filter(m=>m.id);if(converted.length!==rows.length)throw new Error('Una o più righe non hanno il codice apparecchio.');const result=await api<{imported:number;locals:number;duplicate:boolean;message?:string}>('machines/import',{method:'POST',body:JSON.stringify({rows:converted})});if(result.duplicate){setToast('Sinottico già presente: nessuna modifica effettuata');return}await refreshData();setToast(`Importati ${result.imported} apparecchi · ${result.locals} locali`);setPage('Anagrafica');setDetail(null)}catch(e){setToast('Importazione non riuscita: '+(e instanceof Error?e.message:'file non valido'))}}
 async function addDeposit(e:React.FormEvent){e.preventDefault();if(!local||!amount||Number(amount)<=0){setToast('Completa locale e importo');return}try{const {deposit}=await api<{deposit:Deposit}>('deposits',{method:'POST',body:JSON.stringify({local,amount:Number(amount),note})});setData(v=>({...v,deposits:[deposit,...v.deposits]}));setModal(false);setAmount('');setNote('');receipt(deposit);if(selectedLocal)await refreshBoard(selectedLocal.localKey);setToast('Acconto registrato e ricevuta pronta')}catch(e){setToast(e instanceof Error?e.message:'Salvataggio non riuscito')}}
 async function addStaff(){const name=prompt('Nome e cognome del nuovo utente');if(!name?.trim())return;const username=prompt('Nome utente per il login (es. mario.rossi)');if(!username?.trim())return;const role=confirm('Vuoi creare un amministratore? Scegli Annulla per un esattore.')?'admin':'collector';try{const result=await api<{user:Staff;temporaryPassword:string}>('users',{method:'POST',body:JSON.stringify({name:name.trim(),username:username.trim(),role})});setStaff(v=>[...v,result.user]);setData(v=>({...v,collectors:[...v.collectors,result.user.name]}));alert(`Utente creato. Password temporanea da consegnare all’utente:\n\n${result.temporaryPassword}\n\nIl telefono può essere associato con un codice o QR.`);setToast('Utente creato')}catch(e){setToast(e instanceof Error?e.message:'Creazione non riuscita')}}
