 async function saveCompany(value:string){if(!value.trim())return;setSavingCompany(true);try{await api('company',{method:'POST',body:JSON.stringify({company:value,address:companyAddress,vat:companyVat,fiscalCode:companyFiscalCode})});setData(d=>({...d,company:value,companyFiscal:{address:companyAddress,vat:companyVat,fiscalCode:companyFiscalCode}}));setToast('Intestazione aggiornata')}catch(e){setToast(e instanceof Error?e.message:'Salvataggio non riuscito')}finally{setSavingCompany(false)}}
