 {!detail&&page==='Esattori'&&<><div className="pageTitle"><div><div className="eyebrow">UTENTI E DISPOSITIVI</div><h1>Accessi aziendali</h1><p>Crea gli account degli operatori e associa i loro telefoni con un codice monouso o QR.</p></div><button className="primary" onClick={addStaff}><Users size={17}/> Aggiungi utente</button></div><section className="panel people"><div className="panelHead"><div><h2>Utenti attivi</h2><p>La password temporanea viene mostrata una sola volta alla creazione.</p></div></div>{staff.map(u=><div key={u.id}><div className="userAvatar">{u.name.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase()}</div><span><b>{u.name}</b><small>{u.username} · {u.role==='admin'?'Amministratore':'Esattore'}</small></span><button className="outline" onClick={()=>makePairCode(u)}><QrCode size={15}/> Associa telefono</button>{u.id!==auth.id&&<button className="iconBtn" title="Disattiva utente" onClick={()=>disableStaff(u)}><X size={16}/></button>}</div>)}</section><section className="panel people" style={{marginTop:14}}><div className="panelHead"><div><h2>Dispositivi associati</h2><p>Revoca un telefono per chiuderne subito l’accesso.</p></div></div>{devices.length?devices.map(d=><div key={d.id}><div className="userAvatar"><Smartphone size={16}/></div><span><b>{d.label}</b><small>{d.name} · ultimo accesso {shortDate(d.lastSeenAt)}</small></span><button className="danger" onClick={()=>revokeDevice(d.id)}>Revoca</button></div>):<div className="empty"><span>Nessun telefono associato.</span></div>}</section></>}
