function DaySummary({visits,auth,onCancel}:{visits:any[];auth:AuthUser;onCancel:(id:string)=>void}){
 const closed=visits.filter(v=>v.status==='closed'),sum=(key:string)=>closed.reduce((n:number,v:any)=>n+Number(v.totals?.[key]||0),0);
 return <><div className="mobileTotals"><div><small>INCASSI CHIUSI</small><b>{closed.length}</b></div><div><small>GIOCATO</small><b>{money(sum('played'))}</b></div><div><small>TASSE</small><b>{money(sum('taxes'))}</b></div><div><small>RISCOSSO</small><b>{money(sum('collected'))}</b></div></div><section className="panel"><div className="panelHead"><div><h2>Incassi e stato</h2><p>Le operazioni annullate restano visibili per audit.</p></div></div><div className="tableWrap"><table><thead><tr><th>LOCALE</th><th>ESATTORE</th><th>ORA</th><th>STATO</th><th>RISCOSSO</th><th></th></tr></thead><tbody>{visits.map(v=><tr key={v.id}><td><b>{v.local}</b></td><td>{v.collector_name}</td><td>{shortDate(v.started_at)}</td><td><span className={`status ${v.status==='closed'?'on':''}`}>{v.status==='closed'?'Chiuso':v.status==='open'?'Aperto':'Annullato'}</span></td><td className="money">{money(Number(v.totals?.collected||0))}</td><td>{auth.role==='admin'&&v.status!=='cancelled'&&<button className="danger" onClick={()=>onCancel(v.id)}>Annulla</button>}</td></tr>)}</tbody></table></div>{!visits.length&&<div className="empty"><span>Nessuna attività oggi.</span></div>}</section></>
}

async function pinDigest(pin:string,salt:string){const raw=Uint8Array.from(atob(salt),c=>c.charCodeAt(0));const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(pin),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',hash:'SHA-256',salt:raw,iterations:120000},material,256);return Array.from(new Uint8Array(bits),b=>b.toString(16).padStart(2,'0')).join('')}
function PinGate({setup,onDone}:{setup:boolean;onDone:()=>void}){const [pin,setPin]=useState(''),[confirmPin,setConfirmPin]=useState(''),[error,setError]=useState('');async function submit(e:React.FormEvent){e.preventDefault();setError('');if(!/^\d{4,8}$/.test(pin)){setError('Inserisci un PIN da 4 a 8 cifre.');return}if(setup){if(pin!==confirmPin){setError('I PIN non coincidono.');return}const salt=btoa(String.fromCharCode(...crypto.getRandomValues(new Uint8Array(16))));localStorage.setItem('wg_pin_salt',salt);localStorage.setItem('wg_pin_hash',await pinDigest(pin,salt));localStorage.setItem('wg_pin_enabled','1');onDone();return}const salt=localStorage.getItem('wg_pin_salt')||'',expected=localStorage.getItem('wg_pin_hash')||'';if(await pinDigest(pin,salt)!==expected){setError('PIN non corretto.');setPin('');return}onDone()}return <div className="pinShell"><form className="pinCard" onSubmit={e=>void submit(e)}><div className="pinIcon"><LockKeyhole/></div><div className="eyebrow">WINGAMES · ACCESSO RAPIDO</div><h1>{setup?'Crea il PIN del dispositivo':'Inserisci il PIN'}</h1><p>{setup?'Il login è già memorizzato in modo protetto su questo dispositivo.':'Inserisci il PIN per riaprire WinGames senza reinserire le credenziali.'}</p><input autoFocus inputMode="numeric" pattern="[0-9]*" type="password" minLength={4} maxLength={8} value={pin} onChange={e=>setPin(e.target.value.replace(/\D/g,'').slice(0,8))} placeholder="••••"/><>{setup&&<input inputMode="numeric" pattern="[0-9]*" type="password" minLength={4} maxLength={8} value={confirmPin} onChange={e=>setConfirmPin(e.target.value.replace(/\D/g,'').slice(0,8))} placeholder="Ripeti il PIN"/>}</>{error&&<div className="authError">{error}</div>}<button className="primary authSubmit">{setup?'Salva PIN':'Sblocca'}</button></form></div>}

function EntityDetail({ref,auth,data,onBack,onOpen,onSaved,onToast}:{ref:EntityRef;auth:AuthUser;data:Store;onBack:()=>void;onOpen:(ref:EntityRef)=>void;onSaved:()=>void;onToast:(s:string)=>void}){
 const machine=data.machines.find(m=>m.id===ref.id),profile=data.locals.find(l=>l.localKey===ref.id);
 const [history,setHistory]=useState<any[]>([]),[pdaData,setPdaData]=useState<any>({machines:[],history:[]}),[draft,setDraft]=useState<LocalProfile|null>(profile||null),[h1,setH1]=useState(machine?.hopper1||0),[h2,setH2]=useState(machine?.hopper2||0),[busy,setBusy]=useState(false);
 useEffect(()=>{setDraft(profile||null);setH1(machine?.hopper1||0);setH2(machine?.hopper2||0);if(ref.kind==='machine')api<{history:any[]}>(`machines/${encodeURIComponent(ref.id)}/history`).then(r=>setHistory(r.history)).catch(e=>onToast(e.message));else if(ref.kind==='pda')api<any>(`pdas/${encodeURIComponent(ref.id)}`).then(setPdaData).catch(e=>onToast(e.message));else setHistory([])},[ref.kind,ref.id,profile,machine]);
 async function saveHoppers(){setBusy(true);try{await api(`machines/${encodeURIComponent(ref.id)}/hoppers`,{method:'POST',body:JSON.stringify({hopper1:Number(h1),hopper2:Number(h2)})});onToast('Fondi hopper aggiornati');onSaved()}catch(e){onToast(e instanceof Error?e.message:'Salvataggio non riuscito')}finally{setBusy(false)}}
 async function saveLocal(e:React.FormEvent){e.preventDefault();if(!draft)return;setBusy(true);try{await api(`locals/${encodeURIComponent(ref.id)}`,{method:'POST',body:JSON.stringify(draft)});onToast('Anagrafica locale aggiornata');onSaved()}catch(e){onToast(e instanceof Error?e.message:'Salvataggio non riuscito')}finally{setBusy(false)}}
 const field=(label:string,key:keyof LocalProfile)=><label className="detailField">{label}<input value={String(draft?.[key]||'')} disabled={auth.role!=='admin'} onChange={e=>setDraft(v=>v?({...v,[key]:e.target.value}):v)}/></label>;
 return <section className="entityDetail"><div className="detailTop"><button className="outline" onClick={onBack}>← Torna all’elenco</button><span className="eyebrow">{ref.kind==='machine'?'SCHEDA APPARECCHIO':ref.kind==='local'?'SCHEDA LOCALE':'SCHEDA PDA'}</span></div>
 {ref.kind==='machine'&&machine&&<><div className="detailHeading"><div><h1>{machine.id}</h1><p>{machine.local} · {machine.model||'Modello non specificato'}</p></div><span className="status on">{machine.status||'In anagrafica'}</span></div><div className="detailGrid"><div className="detailCard"><h3>Dati apparecchio</h3><dl><dt>CodeID</dt><dd>{machine.id}</dd><dt>Locale</dt><dd><button className="textLink" onClick={()=>onOpen({kind:'local',id:machine.localKey})}>{machine.local}</button></dd><dt>Codice sede / PDV</dt><dd>{machine.localCode||'—'} / {machine.pdvCode||'—'}</dd><dt>Comune / provincia</dt><dd>{[machine.comune,machine.provincia].filter(Boolean).join(' · ')||'—'}</dd><dt>Indirizzo</dt><dd>{machine.address||'—'}</dd><dt>Modello / codice</dt><dd>{machine.model||'—'} · {machine.codeModel||'—'}</dd><dt>Codice provvisorio</dt><dd>{machine.codeProvv||'—'}</dd><dt>Codice esercente</dt><dd>{machine.exerciseCode||'—'}</dd><dt>PDA</dt><dd>{machine.pdaMac?<button className="textLink" onClick={()=>onOpen({kind:'pda',id:machine.pdaMac})}>{machine.pdaMac}</button>:'—'}</dd></dl></div><div className="detailCard"><h3>Contatori e fondo iniziale</h3><div className="counterPair"><div><small>CONTATORE IN</small><b>{machine.cntIn||'—'}</b></div><div><small>CONTATORE OUT</small><b>{machine.cntOut||'—'}</b></div></div><p className="mutedText">I fondi hopper indicano il contenuto iniziale dei due hopper.</p><div className="hopperInputs"><label>Hopper 1 (€)<input type="number" min="0" step="0.01" value={h1} disabled={auth.role!=='admin'} onChange={e=>setH1(Number(e.target.value))}/></label><label>Hopper 2 (€)<input type="number" min="0" step="0.01" value={h2} disabled={auth.role!=='admin'} onChange={e=>setH2(Number(e.target.value))}/></label></div>{auth.role==='admin'&&<button className="primary" disabled={busy} onClick={()=>void saveHoppers()}>Salva fondi hopper</button>}</div></div><div className="detailCard historyCard"><h3>Storico letture e spostamenti AWP</h3><p className="mutedText">Ogni lettura importata conserva locale, PDA, contatori e dati del sinottico.</p>{history.length?<div className="tableWrap"><table><thead><tr><th>DATA LETTURA</th><th>IMPORTATO IL</th><th>LOCALE</th><th>MODELLO</th><th>PDA</th><th>IN</th><th>OUT</th></tr></thead><tbody>{history.map((r:any)=><tr key={r.id}><td>{r.readAt||'—'}</td><td>{r.importedAt?shortDate(r.importedAt):'—'}</td><td>{r.local}</td><td>{r.model||'—'}</td><td>{r.pdaMac||'—'}</td><td>{r.cntIn||'—'}</td><td>{r.cntOut||'—'}</td></tr>)}</tbody></table></div>:<div className="empty"><span>Nessuna lettura storica disponibile.</span></div>}{history[0]?.raw&&<details className="rawDetails"><summary>Altri dati presenti nel sinottico</summary><pre>{JSON.stringify(JSON.parse(history[0].raw),null,2)}</pre></details>}</div><div className="detailCard historyCard"><h3>Acconti registrati nel locale</h3><div className="tableWrap"><table><thead><tr><th>DATA E ORA</th><th>ESATTORE</th><th>IMPORTO</th><th>NOTE</th></tr></thead><tbody>{data.deposits.filter(d=>d.local===machine.local).map(d=><tr key={d.id}><td>{shortDate(d.date)}</td><td>{d.collector}</td><td className="money">{money(d.amount)}</td><td>{d.note||'—'}</td></tr>)}</tbody></table></div>{!data.deposits.some(d=>d.local===machine.local)&&<div className="empty"><span>Nessun acconto registrato per questo locale.</span></div>}</div></>}
 {ref.kind==='local'&&draft&&<><div className="detailHeading"><div><h1>{draft.insegna||draft.name}</h1><p>{[draft.address,draft.comune,draft.provincia].filter(Boolean).join(' · ')}</p></div><span className="status">{data.machines.filter(m=>m.localKey===ref.id).length} apparecchi</span></div><form className="detailCard localForm" onSubmit={saveLocal}><div className="localFields">{field('Nome locale','name')}{field('Insegna','insegna')}{field('Ragione sociale','ragioneSociale')}{field('Partita IVA','partitaIva')}{field('Codice fiscale','codiceFiscale')}{field('Codice sede','localCode')}{field('Codice PDV AAMS','pdvCode')}{field('Indirizzo','address')}{field('Comune','comune')}{field('Provincia','provincia')}{field('Nome contatto','contactName')}{field('Telefono','phone')}{field('Email','email')}{field('PEC','pec')}{field('Percentuale rete (%)','retePercent')}{field('Quota esercente (%)','exercisePercent')}<label className="detailField spanTwo">Note<textarea value={draft.notes||''} disabled={auth.role!=='admin'} onChange={e=>setDraft(v=>v?({...v,notes:e.target.value}):v)}/></label></div>{auth.role==='admin'&&<button className="primary" disabled={busy}>Salva anagrafica</button>}</form><div className="detailCard historyCard"><h3>Macchine presenti nel locale</h3><div className="tableWrap"><table><thead><tr><th>CODEID</th><th>MODELLO</th><th>CONTATORI IN/OUT</th><th>PDA</th></tr></thead><tbody>{data.machines.filter(m=>m.localKey===ref.id).map(m=><tr key={m.id}><td><button className="textLink" onClick={()=>onOpen({kind:'machine',id:m.id})}>{m.id}</button></td><td>{m.model}</td><td>{m.cntIn} / {m.cntOut}</td><td>{m.pdaMac?<button className="textLink" onClick={()=>onOpen({kind:'pda',id:m.pdaMac})}>{m.pdaMac}</button>:'—'}</td></tr>)}</tbody></table></div><h3>PDA presenti</h3><div className="pdaChips">{[...new Set(data.machines.filter(m=>m.localKey===ref.id).map(m=>m.pdaMac).filter(Boolean))].map(mac=><button className="outline" key={mac} onClick={()=>onOpen({kind:'pda',id:mac})}><QrCode size={14}/>{mac}</button>)}</div></div></>}
 {ref.kind==='local'&&!draft&&<div className="detailCard"><h2>Locale non trovato</h2><button className="outline" onClick={onBack}>Torna all’elenco</button></div>}
 {ref.kind==='machine'&&!machine&&<div className="detailCard"><h2>Apparecchio non trovato</h2><button className="outline" onClick={onBack}>Torna all’elenco</button></div>}
 {ref.kind==='pda'&&<><div className="detailHeading"><div><h1>{ref.id}</h1><p>MACADDRESS PDA · {pdaData.machines?.length||0} macchine collegate</p></div></div><div className="detailCard historyCard"><h3>Macchine collegate</h3><div className="tableWrap"><table><thead><tr><th>CODEID</th><th>LOCALE</th><th>MODELLO</th><th>STATO</th><th>IN / OUT</th></tr></thead><tbody>{pdaData.machines?.map((m:any)=><tr key={m.id}><td><button className="textLink" onClick={()=>onOpen({kind:'machine',id:m.id})}>{m.id}</button></td><td>{m.local}</td><td>{m.model||'—'}</td><td>{m.status||'—'}</td><td>{m.cntIn||'—'} / {m.cntOut||'—'}</td></tr>)}</tbody></table></div><h3>Storico macchine associate al PDA</h3><div className="tableWrap"><table><thead><tr><th>DATA LETTURA</th><th>CODEID</th><th>LOCALE</th><th>MODELLO</th><th>CONTATORI IN/OUT</th></tr></thead><tbody>{pdaData.history?.map((r:any,i:number)=><tr key={`${r.importId}:${r.machineId}:${i}`}><td>{r.readAt||'—'}</td><td><button className="textLink" onClick={()=>onOpen({kind:'machine',id:r.machineId})}>{r.machineId}</button></td><td>{r.local}</td><td>{r.model||'—'}</td><td>{r.cntIn||'—'} / {r.cntOut||'—'}</td></tr>)}</tbody></table></div></div></>}
 </section>
}

export default function WinGamesApp(){
 const [auth,setAuth]=useState<AuthUser|null|undefined>(undefined),[needsSetup,setNeedsSetup]=useState(false),[error,setError]=useState(''),[mode,setMode]=useState<'login'|'pair'>('login'),[busy,setBusy]=useState(false),[pairCode,setPairCode]=useState('');
 const autoPairTried=useRef(false);
 useEffect(()=>{if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>undefined)},[]);
 useEffect(()=>{let alive=true;Promise.all([api<{needsSetup:boolean}>('setup-status'),api<{user:AuthUser|null}>('me')]).then(([setup,current])=>{if(!alive)return;setNeedsSetup(setup.needsSetup);setAuth(current.user);const code=new URLSearchParams(location.search).get('pair');if(code&&!current.user&&!setup.needsSetup&&!autoPairTried.current){autoPairTried.current=true;void pair(code)}}).catch(e=>{if(alive){setError(e instanceof Error?e.message:'Impossibile collegarsi al server');setAuth(null)}});return()=>{alive=false}},[]);
 async function pair(code:string){setBusy(true);setError('');try{const result=await api<{user:AuthUser}>('pair',{method:'POST',body:JSON.stringify({code,label:/Android|iPhone|iPad/i.test(navigator.userAgent)?'Telefono':'Dispositivo web'})});setAuth(result.user);setNeedsSetup(false);history.replaceState({},'',location.pathname)}catch(e){setError(e instanceof Error?e.message:'Codice non valido')}finally{setBusy(false)}}
 async function login(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const fd=new FormData(e.currentTarget);setBusy(true);setError('');try{const result=await api<{user:AuthUser}>('login',{method:'POST',body:JSON.stringify({username:fd.get('username'),password:fd.get('password')})});setAuth(result.user)}catch(e){setError(e instanceof Error?e.message:'Accesso non riuscito')}finally{setBusy(false)}}
 async function setup(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const fd=new FormData(e.currentTarget);setBusy(true);setError('');try{const result=await api<{user:AuthUser}>('setup',{method:'POST',body:JSON.stringify({key:fd.get('key'),username:fd.get('username'),name:fd.get('name'),password:fd.get('password')})});setAuth(result.user);setNeedsSetup(false)}catch(e){setError(e instanceof Error?e.message:'Configurazione non riuscita')}finally{setBusy(false)}}
 async function logout(){try{await api('logout',{method:'POST',body:'{}'})}finally{setAuth(null);setMode('login')}}
 if(auth===undefined)return <div className="authShell"><div className="authCard"><div className="authLogo">W</div><b>Connessione al gestionale…</b></div></div>;
 if(auth)return <Dashboard auth={auth} onLogout={()=>void logout()}/>;
 return <div className="authShell"><div className="authCard"><div className="authBrand"><div className="authLogo">W</div><div><b>win<span>games</span></b><small>GESTIONALE AZIENDALE</small></div></div><div className="eyebrow">ACCESSO PROTETTO</div><h1>{needsSetup?'Configura il primo amministratore':mode==='login'?'Accedi a WinGames':'Associa questo dispositivo'}</h1><p className="authLead">{needsSetup?'Crea l’account amministratore della tua azienda.':'I dati aziendali sono visibili solo agli utenti autorizzati.'}</p>{error&&<div className="authError">{error}</div>}
 {needsSetup?<form onSubmit={setup}><label>Codice iniziale<input name="key" type="password" autoComplete="off" required/></label><label>Nome e cognome<input name="name" autoComplete="name" required/></label><label>Nome utente<input name="username" autoComplete="username" minLength={3} required/></label><label>Password amministratore<input name="password" type="password" autoComplete="new-password" minLength={12} required/><small>Almeno 12 caratteri.</small></label><button className="primary authSubmit" disabled={busy}>{busy?'Configurazione…':'Crea amministratore'}</button></form>:mode==='login'?<><form onSubmit={login}><label>Nome utente<input name="username" autoComplete="username" required/></label><label>Password<input name="password" type="password" autoComplete="current-password" required/></label><button className="primary authSubmit" disabled={busy}>{busy?'Accesso…':'Accedi'}</button></form><button className="authSwitch" onClick={()=>{setMode('pair');setError('')}}>Hai un codice o un QR per associare il telefono?</button></>:<form onSubmit={e=>{e.preventDefault();void pair(pairCode)}}><label>Codice monouso<input inputMode="numeric" autoComplete="one-time-code" maxLength={8} placeholder="00000000" value={pairCode} onChange={e=>setPairCode(e.target.value.replace(/\D/g,'').slice(0,8))} required/></label><button className="primary authSubmit" disabled={busy||pairCode.length!==8}>{busy?'Associazione…':'Associa dispositivo'}</button><button type="button" className="authSwitch" onClick={()=>{setMode('login');setError('')}}>Torna al login</button><p className="pairHint">Per associare con QR, inquadra il codice con la fotocamera del telefono e apri il collegamento.</p></form>}
 <div className="authFooter"><ShieldCheck size={15}/> Connessione protetta · Accessi registrati</div></div></div>
}
